# Functions
def make_student(name, age, *scores, city='Chengdu', note=None):
    # Create a student info dict
    def average(nums):
        if not nums:
            return 0
        return sum(nums) / len(nums)

    def level(avg):
        if avg >= 90:
            return 'A'
        elif avg >= 80:
            return 'B'
        elif avg >= 60:
            return 'C'
        else:
            return 'D'

    avg = average(scores)

    info = {
        'name': name,
        'age': age,
        'city': city,
        'scores': tuple(scores),
        'average': round(avg, 2),
        'level': level(avg)
    }

    if note != None:
        info['note'] = note

    return info


def report(students):
    # Print student report
    print('===== Student Report =====')
    for s in students:
        print(f"{s['name']} ({s['age']}) from {s['city']}")
        print(f"  scores : {s['scores']}")
        print(f"  average: {s['average']}")
        print(f"  level  : {s['level']}")
        if s.get('note') != None:
            print(f"  note   : {s['note']}")
        print('-' * 26)


s1 = make_student('MiniPy', 18, 90, 85, 88)
s2 = make_student('Py', 20, 70, 65, 80, city='Beijing', note='Needs practice')
s3 = make_student('Code', 19, 55, 60, 58, city='Shanghai')

report([s1, s2, s3])
